s .election-story h3{font-size:.8rem;margin-bottom:.35rem}.election-details .election-story p{font-size:.75rem}@media(max-width:767.98px){.vote-hero{gap:.6rem}.vote-phase{min-width:0;padding:.42rem .6rem}.vote-info>div{align-items:flex-start;display:block}.vote-info h2{white-space:normal}.vote-info .badge{margin-left:41px}.vote-success{align-items:center;flex-wrap:wrap}.vote-receipt{border-left:0;border-top:1px solid #a7f3d0;grid-template-columns:1fr auto;margin-left:45px;padding:.45rem 0 0;width:calc(100% - 45px)}.candidate-heading p{display:none}.election-details .election-story{grid-template-columns:1fr}}@media(max-width:575.98px){.vote-hero h1{font-size:1rem}.vote-hero p{max-width:92%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.vote-info{align-items:center}.vote-info p{line-height:1.25}.vote-info .badge{display:none}.success-copy p{display:none}.vote-receipt span{display:none}}
.vote-casting-overlay{align-items:center;background:radial-gradient(circle at top,#1d4ed8 0,#0f172a 68%);display:flex;inset:0;justify-content:center;padding:1rem;position:fixed;z-index:2200}.vote-casting-overlay[hidden]{display:none}.vote-casting-stage{color:#fff;max-width:460px;position:relative;text-align:center;width:100%}.vote-paper{align-items:center;animation:votePaperDrop 1.35s cubic-bezier(.2,.8,.2,1) forwards;background:#fff;border:2px solid #bfdbfe;border-radius:18px;box-shadow:0 24px 50px rgba(2,6,23,.38);color:#0f172a;display:flex;flex-direction:column;height:190px;justify-content:center;margin:0 auto -48px;opacity:0;position:relative;transform:translateY(-90px) rotate(-7deg);width:230px;z-index:2}.vote-paper small{color:#64748b;font-size:.68rem;font-weight:900;letter-spacing:.15em}.vote-paper>strong{font-size:1.65rem;font-weight:900;margin-top:.25rem}.vote-stamp{align-items:center;animation:voteStamp .55s .45s cubic-bezier(.3,1.6,.5,1) both;border:5px solid #dc2626;border-radius:50%;color:#dc2626;display:flex;flex-direction:column;height:92px;justify-content:center;position:absolute;right:12px;top:78px;transform:rotate(-13deg) scale(2);width:92px}.vote-stamp i{font-size:1.35rem}.vote-stamp span{font-size:.58rem;font-weight:900;letter-spacing:.05em}.vote-box{background:linear-gradient(145deg,#0f766e,#115e59);border:7px solid rgba(255,255,255,.2);border-radius:24px;box-shadow:0 22px 55px rgba(2,6,23,.35);color:#fff;display:flex;flex-direction:column;font-size:3.5rem;height:155px;justify-content:center;margin:auto;position:relative;width:300px;z-index:3}.vote-box::before{background:#082f49;border-radius:999px;content:"";height:12px;left:50%;position:absolute;top:19px;transform:translateX(-50%);width:160px}.vote-box span{font-size:.62rem;font-weight:900;letter-spacing:.1em;margin-top:.2rem}.vote-casting-stage h2{color:#fff;font-size:1.35rem;font-weight:900;margin:1.4rem 0 .25rem}.vote-casting-stage p{color:rgba(255,255,255,.72);margin:0}.vote-confetti{animation:voteConfetti 1.4s ease-out infinite;background:#fbbf24;height:12px;position:absolute;top:20%;width:7px}.confetti-1{left:8%}.confetti-2{animation-delay:.2s;background:#2dd4bf;left:24%}.confetti-3{animation-delay:.35s;background:#f472b6;right:22%}.confetti-4{animation-delay:.1s;right:6%}@keyframes votePaperDrop{0%{opacity:0;transform:translateY(-100px) rotate(-7deg)}35%{opacity:1}70%{opacity:1;transform:translateY(0) rotate(2deg)}100%{opacity:0;transform:translateY(125px) rotate(0) scale(.75)}}@keyframes voteStamp{to{transform:rotate(-13deg) scale(1)}}@keyframes voteConfetti{0%{opacity:0;transform:translateY(-30px) rotate(0)}25%{opacity:1}100%{opacity:0;transform:translateY(230px) rotate(300deg)}}@media(max-width:575.98px){.vote-box{width:min(82vw,300px)}.vote-paper{height:170px;width:210px}}@media(prefers-reduced-motion:reduce){.vote-paper,.vote-stamp,.vote-confetti{animation-duration:.01ms;animation-delay:0s}}
</style>
@stop

@section('js')
<script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script>
<script>
const selectVotePackage=trigger=>{
    const card=trigger.closest('.vote-package');
    document.querySelectorAll('.vote-package.is-selected').forEach(item=>{item.classList.remove('is-selected');item.querySelector('.card-choice-surface')?.setAttribute('aria-pressed','false')});
    card?.classList.add('is-selected');
    card?.querySelector('.card-choice-surface')?.setAttribute('aria-pressed','true');
    $('#votePackageId').val(trigger.dataset.package);
    $('#chosenNumber').text(trigger.dataset.number);
    $('#chosenName').text(trigger.dataset.name);
    window.setTimeout(()=>{$('#voteModal').modal('show');setTimeout(()=>document.querySelector('#voteForm input[name="password"]')?.focus(),350)},180);
};
$('.btn-choose').on('click',function(event){event.stopPropagation();selectVotePackage(this)});
$('.card-choice-surface').on('click',function(){selectVotePackage(this)});
let voteSubmitting=false;
$('#voteForm').on('submit',function(event){
    event.preventDefault();
    if(voteSubmitting||!this.reportValidity())return;
    voteSubmitting=true;
    const form=this,button=$('#submitVote'),overlay=document.getElementById('voteCastingOverlay');
    button.prop('disabled',true).html('<i class="fas fa-spinner fa-spin mr-1"></i>Mengamankan suara...');
    $('#voteModal').modal('hide');
    document.getElementById('castingNumber').textContent=document.getElementById('chosenNumber').textContent;
    overlay.hidden=false;
    document.body.style.overflow='hidden';
    const delay=window.matchMedia('(prefers-reduced-motion: reduce)').matches?250:1650;
    window.setTimeout(()=>HTMLFormElement.prototype.submit.call(form),delay);
});
window.addEventListener('pageshow',()=>{voteSubmitting=false;$('#submitVote').prop('disabled',false).html('<i class="fas fa-paper-plane mr-1"></i>Kirim Suara');const overlay=document.getElementById('voteCastingOverlay');if(overlay)overlay.hidden=true;document.body.style.overflow=''});
const c=document.getElementById('voteCountdown');if(c){const start=new Date(c.dataset.start),end=new Date(c.dataset.end);const tick=()=>{const now=new Date(),target=now<start?start:end,d=Math.max(0,target-now),days=Math.floor(d/86400000),h=Math.floor(d%86400000/3600000),m=Math.floor(d%3600000/60000);c.textContent=d<=0?'Jadwal selesai':(now<start?'Dibuka dalam ':'Berakhir dalam ')+(days?days+' hari ':'')+h+'j '+m+'m'};tick();setInterval(tick,60000)}
const voteFeedback=@json(session('error') ?: ($errors->any() ? $errors->first() : null));
const previousPackage=@json(old('package_id'));
if(voteFeedback){Swal.fire({icon:'error',title:'Suara belum tersimpan',text:voteFeedback,confirmButtonColor:'#2563eb'}).then(()=>{if(previousPackage){const button=document.querySelector(`.btn-choose[data-package="${previousPackage}"]`);if(button)selectVotePackage(button)}})}
</script>
@stop
